import{_ as n,a0 as d,w as r,s as p,ao as o,I as s,x as l,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Tlog：錄製/播放終端 IO 和會話的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Tlog：錄製/播放終端 IO 和會話的工具 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Tlog：錄製/播放終端 IO 和會話的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Tlog：錄製/播放終端 IO 和會話的工具 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180104 Tlog - A Tool to Record - Play Terminal IO and Sessions","title":"Tlog：錄製/播放終端 IO 和會話的工具","tag":"201803","desc":""},"relativePath":"201803/20180104 Tlog - A Tool to Record - Play Terminal IO and Sessions.md","filePath":"[post].md"}'),g={name:"201803/20180104 Tlog - A Tool to Record - Play Terminal IO and Sessions.md"};function h(u,e,c,k,b,f){const t=d("Link");return r(),p("div",null,[e[19]||(e[19]=o('<h1 id="tlog-錄製-播放終端-io-和會話的工具" tabindex="-1">Tlog：錄製/播放終端 IO 和會話的工具 <a class="header-anchor" href="#tlog-錄製-播放終端-io-和會話的工具" aria-label="Permalink to “Tlog：錄製/播放終端 IO 和會話的工具”">​</a></h1><p>Tlog 是 Linux 中終端 I/O 錄製和回放軟件包。它用於實現一個集中式用户會話錄製。它將所有經過的消息錄製為 JSON 消息。錄製為 JSON 格式的主要目的是將數據傳送到 ElasticSearch 之類的存儲服務，可以從中搜索和查詢，以及回放。同時，它們保留所有通過的數據和時序。</p><p>Tlog 包含三個工具，分別是 <code>tlog-rec</code>、tlog-rec-session<code>和</code>tlog-play`。</p><ul><li><code>tlog-rec</code> 工具一般用於錄製終端、程序或 shell 的輸入或輸出。</li><li><code>tlog-rec-session</code> 工具用於錄製整個終端會話的 I/O，包括錄製的用户。</li><li><code>tlog-play</code> 工具用於回放錄製。</li></ul><p>在本文中，我將解釋如何在 CentOS 7.4 服務器上安裝 Tlog。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>在安裝之前，我們需要確保我們的系統滿足編譯和安裝程序的所有軟件要求。在第一步中，使用以下命令更新系統倉庫和軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum update</span></span></code></pre></div><p>我們需要安裝此軟件安裝所需的依賴項。在安裝之前，我已經使用這些命令安裝了所有依賴包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install wget gcc</span></span>\n<span class="line"><span># yum install systemd-devel json-c-devel libcurl-devel m4</span></span></code></pre></div>',10)),s("p",null,[e[1]||(e[1]=l("完成這些安裝後，我們可以下載該工具的",-1)),a(t,{href:"https://github.com/Scribery/tlog/releases/download/v3/tlog-3.tar.gz"},{default:i(()=>[...e[0]||(e[0]=[l("源碼包",-1)])]),_:1}),e[2]||(e[2]=l("並根據需要將其解壓到服務器上：",-1))]),e[20]||(e[20]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wget https://github.com/Scribery/tlog/releases/download/v3/tlog-3.tar.gz</span></span>
<span class="line"><span># tar -xvf tlog-3.tar.gz</span></span>
<span class="line"><span># cd tlog-3</span></span></code></pre></div><p>現在，你可以使用我們通常的配置和編譯方法開始構建此工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ./configure --prefix=/usr --sysconfdir=/etc &amp;&amp; make</span></span>
<span class="line"><span># make install</span></span>
<span class="line"><span># ldconfig</span></span></code></pre></div><p>最後，你需要運行 <code>ldconfig</code>。它對命令列中指定目錄、<code>/etc/ld.so.conf</code> 文件，以及信任的目錄（ <code>/lib</code> 和 <code>/usr/lib</code>）中最近的共享庫創建必要的鏈接和緩存。</p><h3 id="tlog-工作流程圖" tabindex="-1">Tlog 工作流程圖 <a class="header-anchor" href="#tlog-工作流程圖" aria-label="Permalink to “Tlog 工作流程圖”">​</a></h3><p><img src="https://linoxide.com/wp-content/uploads/2018/01/Tlog-working-process.png" alt="Tlog working process"></p><p>首先，用户通過 PAM 進行身份驗證登錄。名稱服務交換器（NSS）提供的 <code>tlog</code> 信息是用户的 shell。這初始化了 tlog 部分，並從環境變量/配置文件收集關於實際 shell 的信息，並在 PTY 中啓動實際的 shell。然後通過 syslog 或 sd-journal 開始錄製在終端和 PTY 之間傳遞的所有內容。</p><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>你可以使用 <code>tlog-rec</code> 錄製一個會話並使用 <code>tlog-play</code> 回放它，以測試新安裝的 tlog 是否能夠正常錄製和回放會話。</p><h4 id="錄製到文件中" tabindex="-1">錄製到文件中 <a class="header-anchor" href="#錄製到文件中" aria-label="Permalink to “錄製到文件中”">​</a></h4><p>要將會話錄製到文件中，請在命令列中執行 <code>tlog-rec</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tlog-rec --writer=file --file-path=tlog.log</span></span></code></pre></div><p>該命令會將我們的終端會話錄製到名為 <code>tlog.log</code> 的文件中，並將其保存在命令中指定的路徑中。</p><h4 id="從文件中回放" tabindex="-1">從文件中回放 <a class="header-anchor" href="#從文件中回放" aria-label="Permalink to “從文件中回放”">​</a></h4><p>你可以在錄製過程中或錄製後使用 <code>tlog-play</code> 命令回放錄製的會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tlog-play --reader=file --file-path=tlog.log</span></span></code></pre></div><p>該命令從指定的路徑讀取先前錄製的文件 <code>tlog.log</code>。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,18)),s("p",null,[e[4]||(e[4]=l("Tlog 是一個開源軟件包，可用於實現集中式用户會話錄製。它主要是作為一個更大的用户會話錄製解決方案的一部分使用，但它被設計為獨立且可重用的。該工具可以幫助錄製用户所做的一切，並將其存儲在服務器的某個位置，以備將來參考。你可以從這個",-1)),a(t,{href:"https://github.com/Scribery/tlog/blob/master/README.md"},{default:i(()=>[...e[3]||(e[3]=[l("文檔",-1)])]),_:1}),e[5]||(e[5]=l("中獲得關於這個軟件包使用的更多細節。我希望這篇文章對你有用。請發表你的寶貴建議和意見。",-1))]),e[21]||(e[21]=s("p",null,[s("strong",null,"關於 Saheetha Shameer （作者）")],-1)),e[22]||(e[22]=s("p",null,"我正在擔任高級系統管理員。我是一名快速學習者，有輕微的傾向跟隨行業中目前和正在出現的趨勢。我的愛好包括聽音樂、玩策略遊戲、閲讀和園藝。我對嘗試各種美食也有很高的熱情 😃",-1)),e[23]||(e[23]=s("hr",null,null,-1)),s("p",null,[e[7]||(e[7]=l("via: ",-1)),a(t,{href:"https://linoxide.com/linux-how-to/tlog-tool-record-play-terminal-io-sessions/"},{default:i(()=>[...e[6]||(e[6]=[l("https://linoxide.com/linux-how-to/tlog-tool-record-play-terminal-io-sessions/",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=l("作者：",-1)),a(t,{href:"https://linoxide.com/author/saheethas/"},{default:i(()=>[...e[8]||(e[8]=[l("Saheetha Shameer",-1)])]),_:1}),e[12]||(e[12]=l(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[9]||(e[9]=[l("geekpi",-1)])]),_:1}),e[13]||(e[13]=l(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[10]||(e[10]=[l("wxy",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=l("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[14]||(e[14]=[l("LCTT",-1)])]),_:1}),e[17]||(e[17]=l(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[15]||(e[15]=[l("Linux中國",-1)])]),_:1}),e[18]||(e[18]=l(" 榮譽推出",-1))])])}const x=n(g,[["render",h]]);export{y as __pageData,x as default};
